        if (parameterTypes.length < methodParameterTypes.length - 1) {
            return false;
        }

        // Check non-vararg parameters
        int i;
        for (i = 0; i < methodParameterTypes.length - 1; i++) {
            if (!ClassUtils.isAssignable(parameterTypes[i], methodParameterTypes[i], true)) {
                return false;
            }
        }

        // Check vararg parameters
        final Class<?> varArgParameterType = methodParameterTypes[methodParameterTypes.length - 1].getComponentType();
        if (varArgParameterType == null) {
            return false; // Defensive check
        }

        for (; i < parameterTypes.length; i++) {
            if (!ClassUtils.isAssignable(parameterTypes[i], varArgParameterType, true)) {
                return false;
            }
        }
        return true;
    }

    return parameterTypes.length == methodParameterTypes.length &&
           ClassUtils.isAssignable(parameterTypes, methodParameterTypes, true);
}

